CREATE DATABASE IF NOT EXISTS library_borrowing CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE library_borrowing;
CREATE TABLE users(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(120) NOT NULL,email VARCHAR(190) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,role ENUM('admin','staff','user') NOT NULL DEFAULT 'user',is_verified TINYINT(1) NOT NULL DEFAULT 0,status ENUM('active','disabled') NOT NULL DEFAULT 'active',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE categories(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(100) NOT NULL UNIQUE,description VARCHAR(255) DEFAULT NULL) ENGINE=InnoDB;
CREATE TABLE books(id INT AUTO_INCREMENT PRIMARY KEY,isbn VARCHAR(30) UNIQUE,title VARCHAR(200) NOT NULL,author VARCHAR(150) NOT NULL,category_id INT NULL,publisher VARCHAR(150) NULL,published_year SMALLINT NULL,total_copies INT NOT NULL DEFAULT 1,available_copies INT NOT NULL DEFAULT 1,description TEXT NULL,is_archived TINYINT(1) NOT NULL DEFAULT 0,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,CONSTRAINT fk_book_category FOREIGN KEY(category_id) REFERENCES categories(id) ON DELETE SET NULL,CHECK(total_copies>=0),CHECK(available_copies>=0 AND available_copies<=total_copies)) ENGINE=InnoDB;
CREATE TABLE email_verifications(id INT AUTO_INCREMENT PRIMARY KEY,user_id INT NOT NULL,token_hash CHAR(64) NOT NULL UNIQUE,expires_at DATETIME NOT NULL,used_at DATETIME NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE transactions(id INT AUTO_INCREMENT PRIMARY KEY,user_id INT NOT NULL,book_id INT NOT NULL,type ENUM('borrow','reservation') NOT NULL DEFAULT 'borrow',status ENUM('pending','approved','rejected','released','returned','cancelled','expired') NOT NULL DEFAULT 'pending',request_note VARCHAR(500) NULL,requested_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,approved_by INT NULL,approved_at DATETIME NULL,due_date DATE NULL,released_at DATETIME NULL,returned_at DATETIME NULL,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id),FOREIGN KEY(book_id) REFERENCES books(id),FOREIGN KEY(approved_by) REFERENCES users(id) ON DELETE SET NULL,INDEX(status),INDEX(type),INDEX(requested_at)) ENGINE=InnoDB;
CREATE TABLE activity_logs(id BIGINT AUTO_INCREMENT PRIMARY KEY,user_id INT NULL,action VARCHAR(100) NOT NULL,entity VARCHAR(80) NULL,entity_id INT NULL,details VARCHAR(1000) NULL,ip_address VARCHAR(45) NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE SET NULL,INDEX(created_at),INDEX(action)) ENGINE=InnoDB;

